// Block (composition) — a responsive consent bar assembled from Link, Button, and Stack.
// The composed Components own their look; this Block only arranges consent copy and actions.
import type { ReactNode } from "react";
import { Button } from "../components/Button";
import { Link } from "../components/Link";
import { Stack } from "../layouts/Stack";
import "./CookieConsent.css";

export interface CookieConsentProps {
  message?: ReactNode;
  acceptLabel?: string;
  manageLabel?: string;
  policyHref?: string;
  onAccept?: () => void;
  onManage?: () => void;
  className?: string;
}

export function CookieConsent({
  message = "We use cookies to improve your experience.",
  acceptLabel = "Accept",
  manageLabel = "Manage",
  policyHref,
  onAccept,
  onManage,
  className,
}: CookieConsentProps) {
  return (
    <Stack
      as="section"
      role="region"
      aria-label="Cookie consent"
      direction={{ small: "column", medium: "row" }}
      justify="between"
      align="center"
      gap="medium"
      className={className ? `sd-cookieconsent ${className}` : "sd-cookieconsent"}
    >
      <p className="sd-cookieconsent__message sd-type-body-medium">
        {message}
        {policyHref && (
          <>
            {" "}
            <Link href={policyHref}>Privacy policy</Link>
          </>
        )}
      </p>
      <Stack direction="row" align="center" gap="x-small" className="sd-cookieconsent__actions">
        <Button type="button" variant="secondary" onPress={onManage}>
          {manageLabel}
        </Button>
        <Button type="button" variant="primary" onPress={onAccept}>
          {acceptLabel}
        </Button>
      </Stack>
    </Stack>
  );
}

/* CookieConsent.css — .sd-cookieconsent (Block)
   Full-width arrangement only; Stack owns responsive flow and spacing. */
.sd-cookieconsent {
  width: 100%;
}

.sd-cookieconsent__message {
  margin: 0;
}
